"""Writes the command reference as the static HTML help that ships in the packages (wiki.py help).

The help is a plain HTML5 site that works from the disk (file://) without a server and without anything from the
internet. Every page can be read without JavaScript; the script only adds the search, the theme switch and the copy
buttons. See docs/Help.md for the design.

  index.html                   Home: search, the dialects, the guides and the credits.
  commands/index.html          Every category of every dialect.
  commands/a-z.html            Every command from A to Z.
  commands/<Dialect>-<Cat>.html  One page per category: its introduction and its commands.
  commands/<Name>.html         One page per command.
  pages/<Page>.html            The pages that are not commands (Language, Types, Differences, ...).
  examples/<Name>.bb           The first example of each command, to download.
  assets/                      help.css, help.js, search.js (the search index) and the logo.
  media/                       The images, animations and sounds that the pages use.

Everything is made from the same text as the wiki, so the help is generated while packaging and never committed.
"""
import html
import json
import os
import re
import shutil
import sys

import categories

ESC = html.escape
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.normpath(os.path.join(HERE, "..")))
import generate_vscode_grammar as grammar  # noqa: E402  (the keyword lists of the syntax highlighting)

PRODUCT_CLASS = {"Blitz2D": "bb", "Blitz3D": "b3d", "BlitzPlus": "bp", "BlitzLLVM": "bl"}


# --- Paths -----------------------------------------------------------------------------------------------------------

def category_name(dialect, category):
    return "%s-%s" % (dialect, category.replace(" ", "-"))


class Links:
    """Resolves the targets of wiki links ([Name](Name), [[Name]]) from the page that links to them."""

    def __init__(self, commands, pages, prefix):
        self.commands = {c.name: c for c in commands}
        self.pages = set(pages)
        self.cats = {category_name(*k) for k in categories.CATEGORY_TEXT}
        self.prefix = prefix  # How to get from the page to the help folder: "../" from commands/ and pages/.

    def target(self, name):
        """Returns the href for a wiki page name, or None when the help has no such page."""
        if name == "Command-Index":
            return self.prefix + "commands/a-z.html"
        if name in self.commands:
            return "%scommands/%s.html" % (self.prefix, name)
        if name in self.pages:
            return "%spages/%s.html" % (self.prefix, name)
        if name in self.cats:
            return "%scommands/%s.html" % (self.prefix, name)
        if name in categories.TITLES or name in (categories.BASIC, categories.B3D, categories.PLUS, categories.LANG):
            return "%scommands/index.html#%s" % (self.prefix, name)
        return None


# --- Text ------------------------------------------------------------------------------------------------------------

def slug(text):
    """The id of a heading, the way GitHub makes it, so that links such as Graphics#color-depth work in both."""
    text = re.sub(r"<[^>]+>", "", text).strip().lower()
    return re.sub(r"[^\w\- ]", "", text).replace(" ", "-")


def plain(text):
    """Markdown as plain text, for the search index and the summaries."""
    text = re.sub(r"<[^>]+>", "", text)
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", text)
    text = re.sub(r"\[\[([^\]|]+)\]\]", lambda m: m.group(1).replace("-", " "), text)
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"[`*]", "", text)
    return re.sub(r"\s+", " ", text).strip()


def summary(text, limit=160):
    free = re.sub(r"```.*?```", "", text, flags=re.S)
    free = "\n".join(x for x in free.split("\n") if not x.startswith(("@", "#", "|", "![", "<", ";")))
    first = re.match(r"(.+?[.!?])(?:\s|$)", plain(free))
    s = first.group(1) if first else plain(free)
    return s if len(s) <= limit else s[:limit - 1].rsplit(" ", 1)[0] + "…"


def pill(product, small=False):
    name = {"Blitz2D": "BlitzBasic"}.get(product, product)
    return '<span class="pill %s%s" title="%s">%s</span>' % (
        PRODUCT_CLASS[product], " sm" if small else "", ESC(name), ESC(name))


def pills(c, small=False):
    return '<span class="pills">%s</span>' % "".join(pill(p, small) for p in c.products) if c.products else ""


# The keywords and the names of the commands, for the syntax highlighting of the examples.
KEYWORDS = {k.lower() for group in (grammar.CONTROL, grammar.DECLARATION, grammar.OBJECT) for k in group for k in k.split()}
OPERATORS = {k.lower() for k in grammar.OPERATOR}
CONSTANTS = {k.lower() for k in grammar.CONSTANT}
TYPE_NAMES = {k.lower() for k in grammar.TYPES}
TOKEN = re.compile(r'(?P<c>;.*)|(?P<s>"[^"\n]*"?)|(?P<n>\$[0-9A-Fa-f]+\b|%[01]+\b|\b0[xX][0-9A-Fa-f]+\b|\b0[bB][01]+\b|'
                   r'\b\d+\.\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?|\b\d+\b)|(?P<w>[A-Za-z_]\w*)')


def highlight(code, links):
    """BlitzBasic as HTML with <span>s for the colors; command names link to their pages."""
    names = links.lower_commands
    out, pos = [], 0
    for m in TOKEN.finditer(code):
        out.append(ESC(code[pos:m.start()], quote=False))
        pos = m.end()
        t = m.group(0)
        if m.group("c"):
            out.append('<span class="tc">%s</span>' % ESC(t, quote=False))
        elif m.group("s"):
            out.append('<span class="ts">%s</span>' % ESC(t, quote=False))
        elif m.group("n"):
            out.append('<span class="tn">%s</span>' % t)
        else:
            low = t.lower()
            if low in KEYWORDS:
                out.append('<span class="tk">%s</span>' % t)
            elif low in OPERATORS:
                out.append('<span class="to">%s</span>' % t)
            elif low in CONSTANTS:
                out.append('<span class="tn">%s</span>' % t)
            elif low in TYPE_NAMES and code[m.start() - 1:m.start()] == ":":
                out.append('<span class="tt">%s</span>' % t)
            elif low in names:
                out.append('<a class="tf" href="%s">%s</a>' % (links.target(names[low]), t))
            else:
                out.append(t)
    out.append(ESC(code[pos:], quote=False))
    return "".join(out)


def code_block(code, lang, links, download=None):
    label = {"blitzbasic": "BlitzBasic", "text": "Output", "": "Text"}.get(lang, lang)
    body = highlight(code, links) if lang == "blitzbasic" else ESC(code, quote=False)
    extra = ' <a class="btn" href="%s" download>Download .bb</a>' % download if download else ""
    return ('<figure class="code %s"><figcaption><span>%s</span><span class="tools">%s'
            '<button class="btn copy" type="button" hidden>Copy</button></span></figcaption>'
            '<pre><code>%s</code></pre></figure>' % ("out" if lang == "text" else "bb", label, extra, body))


def media_tag(path, alt, prefix):
    src = prefix + path
    if path.endswith((".ogg", ".wav", ".mp3")):
        # A link that the script turns into a play button, so that sounds sit in the text like any other link.
        return '<a class="play" href="%s" title="Play">%s</a>' % (src, alt)
    return '<img src="%s" alt="%s" loading="lazy">' % (src, ESC(alt))


def inline(text, links, media):
    """Markdown inside a line: code, images, links, bold and italics. Anything that is already HTML is kept."""
    parts = []

    def keep(s):
        parts.append(s)
        return "\x00%d\x00" % (len(parts) - 1)

    text = re.sub(r"`([^`]+)`", lambda m: keep("<code>%s</code>" % ESC(m.group(1), quote=False)), text)
    text = re.sub(r"<!--.*?-->", "", text)
    # The product icons of the wiki become the pills of the help.
    text = re.sub(r'<img class="product"[^>]*alt="([^"]+)"[^>]*>',
                  lambda m: keep(pill({"BlitzBasic": "Blitz2D"}.get(m.group(1), m.group(1)), True)), text)
    text = re.sub(r"(<[a-zA-Z/][^>]*>)", lambda m: keep(rewrite_html(m.group(1), links, media)), text)

    def image(m):
        media.add(m.group(2))
        return keep(media_tag(m.group(2), m.group(1), links.prefix))

    text = re.sub(r"!\[([^\]]*)\]\(([^)\s]+)\)", image, text)

    def link(label, name):
        name, _, anchor = name.partition("#")
        if name.startswith("media/"):
            media.add(name)
            if name.endswith((".ogg", ".wav", ".mp3")):
                return keep(media_tag(name, label, links.prefix))
            name = links.prefix + name
        if not name and anchor:
            return keep('<a href="#%s">%s</a>' % (anchor, label))
        href = links.target(name) if re.fullmatch(r"[A-Za-z0-9_-]+", name) else name
        if href is None:
            return label
        if re.match(r"https?://", href):
            return keep('<a href="%s" rel="noopener">%s</a>' % (href, label))
        return keep('<a href="%s%s">%s</a>' % (href, "#" + anchor if anchor and "#" not in href else "", label))

    text = re.sub(r"\[\[([^\]|]+)\]\]", lambda m: link(ESC(m.group(1).replace("-", " ")), m.group(1)), text)
    text = re.sub(r"\[([^\]]+)\]\(([^)\s]+)\)", lambda m: link(m.group(1), m.group(2)), text)
    text = ESC(text, quote=False)
    text = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", text)
    text = re.sub(r"(?<![\w*])\*([^*\s][^*]*?)\*(?![\w*])", r"<em>\1</em>", text)
    text = re.sub(r"(?<![\w])_([^_\s][^_]*?)_(?![\w])", r"<em>\1</em>", text)
    while "\x00" in text:
        text = re.sub("\x00(\\d+)\x00", lambda m: parts[int(m.group(1))], text)
    return text


def rewrite_html(tag, links, media):
    def src(m):
        if m.group(2).startswith("media/"):
            media.add(m.group(2))
            return '%s"%s%s"' % (m.group(1), links.prefix, m.group(2))
        return m.group(0)

    return re.sub(r'(src=)"([^"]+)"', src, tag)


def markdown(text, links, media, level=1, toc=None):
    """Converts the Markdown subset the wiki text uses to HTML. level is the heading level of a '#'. Headings of level
    2 are added to toc as (id, text) when it is a list."""
    lines = text.split("\n")
    out, i = [], 0
    para = []

    def flush():
        if para:
            out.append("<p>%s</p>" % inline(" ".join(para), links, media))
            para.clear()

    while i < len(lines):
        line = lines[i]
        if line.startswith("```"):
            flush()
            lang, code, i = line[3:].strip(), [], i + 1
            while i < len(lines) and not lines[i].startswith("```"):
                code.append(lines[i])
                i += 1
            code = [x for x in code if not re.match(r"^;(media .*|run|nocompile)$", x)]
            out.append(code_block("\n".join(code), lang, links))
        elif not line.strip():
            flush()
        elif re.match(r"^#{1,6} ", line):
            flush()
            n = len(line) - len(line.lstrip("#"))
            content = inline(line[n + 1:], links, media)
            hid = slug(line[n + 1:])
            h = n + level - 1
            if toc is not None and h == 2:
                toc.append((hid, re.sub(r"<[^>]+>", "", content)))
            out.append('<h%d id="%s">%s<a class="anchor" href="#%s" aria-label="Link to this section">#</a></h%d>'
                       % (h, hid, content, hid, h))
        elif line.startswith("|"):
            flush()
            rows = []
            while i < len(lines) and lines[i].startswith("|"):
                rows.append([c.strip() for c in lines[i].strip().strip("|").split("|")])
                i += 1
            i -= 1
            out.append('<div class="table"><table>')
            for r, row in enumerate(rows):
                if r == 1 and all(re.fullmatch(r":?-+:?", c) for c in row):
                    continue
                tag = "th" if r == 0 else "td"
                out.append("<tr>%s</tr>" % "".join("<%s>%s</%s>" % (tag, inline(c, links, media), tag) for c in row))
            out.append("</table></div>")
        elif re.match(r"^\s*([*-]|\d+\.) ", line):
            flush()
            tag = "ol" if re.match(r"^\s*\d+\. ", line) else "ul"
            items = []
            while i < len(lines) and re.match(r"^\s*([*-]|\d+\.) ", lines[i]):
                items.append(re.sub(r"^\s*([*-]|\d+\.) ", "", lines[i]))
                i += 1
            i -= 1
            out.append("<%s>%s</%s>" % (tag, "".join("<li>%s</li>" % inline(x, links, media) for x in items), tag))
        elif line.startswith("> "):
            flush()
            quote = []
            while i < len(lines) and lines[i].startswith(">"):
                quote.append(lines[i][1:].strip())
                i += 1
            i -= 1
            out.append('<aside class="note">%s</aside>' % markdown("\n".join(quote), links, media, level))
        elif line.startswith("<") and not re.match(r"^<(a|b|i|code|img|em|strong)[ >]", line):
            flush()
            out.append(inline(line, links, media))
        else:
            para.append(line.strip())
        i += 1
    flush()
    return "\n".join(out)


