def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


class Site:
    """What every page needs: the commands, the pages and the navigation."""

    def __init__(self, commands, wiki, out):
        self.commands, self.wiki, self.out = commands, wiki, out
        self.media = set()
        self.sources = wiki.page_sources(commands)
        self.page_names = list(self.sources)
        self.cats = {}
        for c in commands:
            self.cats.setdefault((c.dialect, c.category), []).append(c)
        for k in self.cats:
            self.cats[k].sort(key=lambda c: c.name.lower())
        order = list(categories.CATEGORY_TEXT)
        self.cat_order = sorted(self.cats, key=lambda k: (wiki.DIALECT_ORDER.index(k[0]),
                                                          order.index(k) if k in order else len(order), k[1]))
        self.lower = {}
        for c in sorted(commands, key=lambda c: (c.module == "keyword", c.name)):
            self.lower.setdefault(c.name.lower(), c.name)
        # The pages, grouped as in the sidebar of the wiki (wiki.GROUPS), then the other pages, then Differences.
        titles = {n: t for n, t, _ in self.sources.values()}
        groups = [(g, [n for n in names if n in titles]) for g, names in wiki.GROUPS]
        listed = {n for _, names in groups for n in names} | {"Differences"}
        groups.append(("Features", sorted((n for n in titles if n not in listed), key=lambda n: titles[n].lower())))
        groups.append(("Differences", ["Differences"]))
        self.groups = [(g, names) for g, names in groups if names]
        self.titles = titles

    def links(self, prefix):
        links = Links(self.commands, self.page_names, prefix)
        links.lower_commands = self.lower
        return links

    def nav(self, here, current=None, current_cat=None):
        """The sidebar: the guides, then the dialects with their categories. The category of the page is open and
        lists its commands. here is the folder of the page, so that links within it stay short."""
        prefix = "../" if here else ""

        def href(target):
            return target[len(here) + 1:] if here and target.startswith(here + "/") else prefix + target

        def item(target, text, is_current, extra=""):
            return '<a href="%s"%s>%s%s</a>' % (href(target), ' aria-current="page"' if is_current else "", text, extra)

        out = ['<div class="nav-group">%s%s</div>' % (
            item("index.html", "Home", current == "home"), item("commands/a-z.html", "All commands A-Z", current == "a-z")),
            '<p class="nav-label">Guides</p>']
        for g, names in self.groups:
            out.append('<details class="nav-group"%s><summary>%s</summary><ul>%s</ul></details>' % (
                " open" if current in names or g == "Language" else "", ESC(g), "".join(
                    "<li>%s</li>" % item("pages/%s.html" % n, ESC(self.titles[n]), n == current) for n in names)))
        out.append('<p class="nav-label">Commands</p>')
        for dialect in self.wiki.DIALECT_ORDER:
            items = []
            for k in (k for k in self.cat_order if k[0] == dialect):
                name = category_name(*k)
                sub = ""
                if k == current_cat:
                    sub = '<ul class="cmds">%s</ul>' % "".join(
                        "<li>%s</li>" % item("commands/%s.html" % c.name, ESC(c.name), c.name == current)
                        for c in self.cats[k])
                items.append("<li%s>%s%s</li>" % (
                    ' class="open"' if k == current_cat else "",
                    item("commands/%s.html" % name, ESC(categories.display(k[1])), current == name,
                         '<span class="count">%d</span>' % len(self.cats[k])), sub))
            open_ = current_cat is not None and current_cat[0] == dialect
            out.append('<details class="nav-group"%s><summary>%s</summary><ul>%s</ul></details>' % (
                " open" if open_ else "", ESC(categories.TITLES.get(dialect, dialect)), "".join(items)))
        return "\n".join(out)

    def page(self, path, title, body, kind, current=None, current_cat=None, description=None):
        prefix = "../" if "/" in path else ""
        write(os.path.join(self.out, path), PAGE % {
            "root": prefix, "title": ESC(title), "kind": kind, "boot": THEME_BOOT, "body": body,
            "description": '<meta name="description" content="%s">\n' % ESC(description) if description else "",
            "nav": self.nav(os.path.dirname(path), current, current_cat)})


def crumbs(*items):
    return '<nav class="crumbs" aria-label="Breadcrumb"><ol>%s</ol></nav>' % "".join(
        '<li><a href="%s">%s</a></li>' % (h, ESC(t)) if h else '<li aria-current="page">%s</li>' % ESC(t)
        for h, t in items)


def signature_html(c, links):
    if c.syntax:
        return highlight("\n".join(c.syntax), links)
    text = ESC(c.signature(), quote=False)
    text = re.sub(r"^(\w+)", r'<span class="sn">\1</span>', text)
    return re.sub(r":(\w+)", r':<span class="tt">\1</span>', text)


# --- Command pages ---------------------------------------------------------------------------------------------------

def command_page(site, c):
    links = site.links("../")
    media = site.media
    wiki = site.wiki
    free, doc = wiki.split_text(re.sub(r"^;(media .*|run)\n", "", c.text, flags=re.M))
    media_lines = re.findall(r"^!\[[^\]]*\]\([^)]+\)[ \t]*$", free, re.M)
    free = re.sub(r"^!\[[^\]]*\]\([^)]+\)[ \t]*\n?", "", free, flags=re.M).strip()
    m = re.search(r"^```", free, re.M)
    description, examples = (free[:m.start()], free[m.start():]) if m else (free, "")
    key = (c.dialect, c.category)
    cat = category_name(*key)
    dialect_title = categories.TITLES.get(c.dialect, c.dialect)

    out = [crumbs(("../commands/index.html#%s" % c.dialect, dialect_title),
                  ("%s.html" % cat, categories.display(c.category)), (None, c.name))]
    out.append('<header class="title"><h1>%s</h1>%s</header>' % (ESC(c.name), pills(c)))
    out.append('<pre class="signature"><code>%s</code></pre>' % signature_html(c, links))
    if c.extension:
        out.append('<aside class="note new"><strong>New in BlitzLLVM.</strong> The original Blitz products do not '
                   'have this command.</aside>')
    lead = description.strip()
    out.append('<section id="description">%s</section>' % (
        markdown(lead, links, media, level=2) if lead else '<p class="muted">Not documented yet.</p>'))
    if c.params:
        rows = []
        for mode, t, n, d in c.modes():
            tags = "".join('<span class="tag">%s</span>' % x for x in (
                [mode.strip()] if mode.strip() else []) + (["optional, default %s" % ESC(d)] if d else []))
            rows.append('<tr><th scope="row"><code>%s</code></th><td><code class="tt">%s</code></td>'
                        '<td>%s%s</td></tr>' % (ESC(n), ESC(t), inline(doc["param"].get(n, ""), links, media), tags))
        out.append('<section id="parameters"><h2>Parameters</h2><div class="table"><table class="params">'
                   '<thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody>%s</tbody></table>'
                   '</div></section>' % "".join(rows))
    if doc["returns"] or c.ret != "Void":
        out.append('<section id="returns"><h2>Returns</h2><p>%s%s</p></section>' % (
            '<code class="tt">%s</code> ' % c.ret if c.ret != "Void" else "", inline(doc["returns"], links, media)))
    if doc["gap"]:
        out.append('<section id="differences"><h2>Differences</h2><aside class="note warn"><ul>%s</ul></aside>'
                   '</section>' % "".join("<li>%s</li>" % inline(g, links, media) for g in doc["gap"]))
    if examples:
        first = re.search(r"```blitzbasic\n(.*?)```", examples, re.S)
        html_ = markdown(examples, links, media, level=3)
        if first:
            html_ = html_.replace('<span class="tools">', '<span class="tools"><a class="btn" href="../examples/%s.bb" '
                                  'download>Download .bb</a>' % c.name, 1)
        count = examples.count("```blitzbasic")
        out.append('<section id="examples"><h2>%s</h2>%s</section>' % ("Examples" if count > 1 else "Example", html_))
    if media_lines:
        out.append('<section id="media"><h2>Media</h2><div class="gallery">%s</div></section>' % "".join(
            inline(x.strip(), links, media) for x in media_lines))
    rel = wiki.related(c, site.cats[key])
    if rel:
        out.append('<section id="related"><h2>Related commands</h2><ul class="chips">%s</ul></section>' % "".join(
            '<li><a href="%s.html">%s</a></li>' % (o.name, ESC(o.name)) for o in rel))
    siblings = site.cats[key]
    i = siblings.index(c)
    prev_, next_ = siblings[i - 1] if i else None, siblings[i + 1] if i + 1 < len(siblings) else None
    out.append('<nav class="pager" aria-label="Neighbours">%s%s</nav>' % (
        '<a class="prev" href="%s.html"><small>Previous</small>%s</a>' % (prev_.name, ESC(prev_.name)) if prev_ else "<span></span>",
        '<a class="next" href="%s.html"><small>Next</small>%s</a>' % (next_.name, ESC(next_.name)) if next_ else "<span></span>"))
    site.page("commands/%s.html" % c.name, c.name, '<article class="doc">%s</article>' % "\n".join(out), "command",
              current=c.name, current_cat=key, description=summary(description))

    first = re.search(r"```blitzbasic\n(.*?)```", free, re.S)
    if first:
        code = "\n".join(x for x in first.group(1).split("\n") if not re.match(r"^;(media .*|run|nocompile)$", x))
        write(os.path.join(site.out, "examples", c.name + ".bb"), code.rstrip("\n") + "\n")


def command_rows(cs, prefix="", summaries=None):
    return '<ul class="cmd-list">%s</ul>' % "".join(
        '<li><a href="%s%s.html"><code>%s</code></a>%s<p>%s</p></li>' % (
            prefix, c.name, ESC(c.name), pills(c, True), ESC(summaries[c.key]) if summaries[c.key] else "")
        for c in cs)


def category_page(site, key, summaries):
    links = site.links("../")
    dialect, category = key
    name = category_name(*key)
    cs = site.cats[key]
    intro = site.wiki.INTROS.get(name, "") or categories.CATEGORY_TEXT.get(key, "")
    body = [crumbs(("index.html#%s" % dialect, categories.TITLES.get(dialect, dialect)), (None, categories.display(category))),
            '<header class="title"><h1>%s</h1></header>' % ESC(categories.display(category))]
    if intro:
        body.append('<div class="intro">%s</div>' % markdown(re.sub(r"^# .*\n", "", intro), links, site.media, level=2))
    body.append('<h2 id="commands">Commands <span class="count">%d</span></h2>' % len(cs))
    body.append(command_rows(cs, "", summaries))
    site.page("commands/%s.html" % name, categories.display(category), '<article class="doc">%s</article>' % "\n".join(body),
              "category", current=name, current_cat=key)


def index_pages(site, summaries):
    links = site.links("../")
    body = ['<article class="doc"><header class="title"><h1>Command reference</h1></header>',
            '<p class="lead">Every command of BlitzBasic, Blitz3D and BlitzPlus as BlitzLLVM implements them, and the '
            'ones BlitzLLVM adds %s. Press <kbd>/</kbd> to search, or pick a category.</p>' % pill("BlitzLLVM", True)]
    for dialect in site.wiki.DIALECT_ORDER:
        keys = [k for k in site.cat_order if k[0] == dialect]
        body.append('<section id="%s"><h2>%s <span class="count">%d</span></h2><p>%s</p><div class="cards">%s</div>'
                    '</section>' % (dialect, ESC(categories.TITLES.get(dialect, dialect)),
                                    sum(len(site.cats[k]) for k in keys),
                                    inline(site.wiki.DIALECT_TEXT.get(dialect, ""), links, site.media), "".join(
                                        '<a class="card" href="%s.html"><b>%s</b><span>%s</span><small>%d commands</small></a>' % (
                                            category_name(*k), ESC(categories.display(k[1])),
                                            ESC(plain(categories.CATEGORY_TEXT.get(k, ""))), len(site.cats[k]))
                                        for k in keys)))
    body.append("</article>")
    site.page("commands/index.html", "Command reference", "\n".join(body), "index")

    everything = sorted(site.commands, key=lambda c: (c.name.lower(), c.dialect))
    letters = sorted({c.name[0].upper() for c in everything})
    body = ['<article class="doc"><header class="title"><h1>All commands <span class="count">%d</span></h1></header>'
            % len(everything),
            '<nav class="letters" aria-label="Letters">%s</nav>' % "".join(
                '<a href="#%s">%s</a>' % (l, l) for l in letters)]
    for l in letters:
        body.append('<section id="%s"><h2>%s</h2>%s</section>' % (
            l, l, command_rows([c for c in everything if c.name[0].upper() == l], "", summaries)))
    body.append("</article>")
    site.page("commands/a-z.html", "All commands", "\n".join(body), "index", current="a-z")


def guide_page(site, name, title, text):
    links = site.links("../")
    toc = []
    html_ = markdown(text, links, site.media, toc=toc)
    side = ""
    if len(toc) > 2:
        side = '<nav class="toc" aria-label="On this page"><b>On this page</b><ul>%s</ul></nav>' % "".join(
            '<li><a href="#%s">%s</a></li>' % (i, t) for i, t in toc)
    site.page("pages/%s.html" % name, title, '<article class="doc guide">%s%s</article>' % (side, html_), "guide",
              current=name, description=summary(text))


def home_page(site):
    wiki = site.wiki
    cards = []
    for dialect in wiki.DIALECT_ORDER:
        n = sum(len(v) for k, v in site.cats.items() if k[0] == dialect)
        cards.append('<a class="card big" href="commands/index.html#%s"><b>%s</b><span>%s</span><small>%d commands</small></a>' % (
            dialect, ESC(categories.TITLES.get(dialect, dialect)), ESC(plain(wiki.DIALECT_TEXT.get(dialect, ""))), n))
    guides = []
    for g, names in site.groups:
        guides.append('<section><h3>%s</h3><ul>%s</ul></section>' % (ESC(g), "".join(
            '<li><a href="pages/%s.html">%s</a></li>' % (n, ESC(site.titles[n])) for n in names)))
    body = """<article class="doc home">
<section class="hero">
<img src="assets/logo.svg" alt="" width="64" height="74">
<div><h1>BlitzLLVM Help</h1>
<p class="lead">The language and every command of BlitzBasic, Blitz3D and BlitzPlus, as BlitzLLVM compiles them, with what
BlitzLLVM adds and where it differs from the originals.</p>
<p><button class="btn primary search-focus" type="button" hidden>Search <kbd>/</kbd></button>
<a class="btn" href="commands/a-z.html">All commands A-Z</a> <a class="btn" href="pages/Differences.html">Differences</a></p></div>
</section>
<h2 id="commands">Commands</h2>
<div class="cards big">%s</div>
<h2 id="guides">Guides</h2>
<div class="columns">%s</div>
<h2 id="credits">Credits</h2>
<p>BlitzLLVM is made by Xaymar and its contributors. Blitz3D, BlitzPlus and BlitzBasic were made by Mark Sibly and
Blitz Research Ltd., whose commands this software implements. See the licenses folder for the libraries BlitzLLVM
uses.</p>
</article>""" % ("".join(cards), "".join(guides))
    site.page("index.html", "Home", body, "home", current="home")


def search_index(site, summaries):
    """assets/search.js: [name, path, kind, where, summary]. kind: 0 command, 1 category, 2 page."""
    rows = []
    for c in sorted(site.commands, key=lambda c: c.name.lower()):
        where = "%s › %s" % (categories.TITLES.get(c.dialect, c.dialect), categories.display(c.category))
        rows.append([c.name, "commands/%s.html" % c.name, 0, where + (" · BlitzLLVM" if c.extension else ""),
                     summaries[c.key]])
    for k in site.cat_order:
        rows.append([categories.display(k[1]), "commands/%s.html" % category_name(*k), 1,
                     categories.TITLES.get(k[0], k[0]), plain(categories.CATEGORY_TEXT.get(k, ""))])
    for name, title, text in site.sources.values():
        rows.append([title, "pages/%s.html" % name, 2, "Guide", summary(text)])
    write(os.path.join(site.out, "assets", "search.js"),
          "window.HELP_INDEX=%s;\n" % json.dumps(rows, ensure_ascii=False, separators=(",", ":")))


def build_help(commands, out, wiki):
    """Writes the whole help into out. wiki is the wiki module (its text and page functions are used)."""
    shutil.rmtree(out, ignore_errors=True)
    site = Site(commands, wiki, out)
    summaries = {c.key: summary(wiki.split_text(c.text)[0]) for c in commands}
    for c in commands:
        command_page(site, c)
    for k in site.cat_order:
        category_page(site, k, summaries)
    index_pages(site, summaries)
    for name, title, text in site.sources.values():
        guide_page(site, name, title, text)
    home_page(site)
    search_index(site, summaries)

    assets = os.path.join(HERE, "help")
    for fn in ("help.css", "help.js"):
        shutil.copyfile(os.path.join(assets, fn), os.path.join(out, "assets", fn))
    shutil.copyfile(os.path.join(wiki.ROOT, "media", "icon-small.svg"), os.path.join(out, "assets", "logo.svg"))
    for m in sorted(site.media):
        src = os.path.join(wiki.WIKI, m)
        if os.path.exists(src):
            os.makedirs(os.path.dirname(os.path.join(out, m)), exist_ok=True)
            shutil.copyfile(src, os.path.join(out, m))
